 static final Map<String,String> MASTER=fields("dataSourceId:DATA_SOURCE_ID,serverName:SERVER_NAME,databaseName:DATABASE_NAME,schemaName:SCHEMA_NAME,objectName:OBJECT_NAME,objectType:OBJECT_TYPE,businessName:BUSINESS_NAME,description:DESCRIPTION,useYn:USE_YN,definitionEvidence:DEFINITION_EVIDENCE,identityEvidence:IDENTITY_EVIDENCE,reviewStatus:REVIEW_STATUS,reviewEvidence:REVIEW_EVIDENCE,pkName:PK_NAME,pkReview:PK_REVIEW,pkEvidence:PK_EVIDENCE");
